        const match = text.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*([KMBT])?$/i);
        if (!match) return null;
        const exponent = ({ K: 3, M: 6, B: 9, T: 12 })[(match[2] || "").toUpperCase()];
        const number = Number(match[1] + (exponent ? "e" + exponent : ""));
        return Number.isFinite(number) ? number : null;
