                    const attributes = part.split(";").map(item => item.trim());
                    const first = attributes.shift().match(/^([!#$%&'*+.^_`|~0-9A-Za-z-]+)=([^;]*)$/);
                    if (!first || /[^\x21-\x7e]|[,"\\]/.test(first[2])) continue;
