/** RSI(2) trigger targets and quote fields. Missing targets remain N/A. @customfunction */
function TICKERSHEETS_RSI_TARGETS(ticker, lowTrigger = 20, highTrigger = 80, field = "all", refresh = "") {
    try {
        const wanted = TickerSheetsRsiTargets.field_(field), result = TickerSheetsRsiTargets.fetch(ticker, lowTrigger, highTrigger, wanted, {}, refresh);
        if (!result?.ok) return TickerSheetsPublicData.error(result);
        if (wanted === "headers") return [result.headers];
        return wanted === "all" ? [TickerSheetsRsiTargets.headers(), TickerSheetsRsiTargets.fields().map(name => TickerSheetsPublicData.safe(result.values[name]))] : TickerSheetsPublicData.safe(result.values[wanted]);
    } catch { return "N/A: RSI2 targets are unavailable"; }
}

/** Exact FRED observation dates identify data periods, not release dates or earlier business days. */
class TickerSheetsExactFred {
    static date_(input) {
        let date = input;
        if (input instanceof Date) {
            if (!Number.isFinite(input.getTime())) return null;
            try {
                const zone = SpreadsheetApp.getActiveSpreadsheet().getSpreadsheetTimeZone();
                date = Utilities.formatDate(input, zone, "yyyy-MM-dd");
            } catch { return null; }
        }
        if (typeof date !== "string") return null;
        date = date.trim();
        return TickerSheetsFred.date_(date) && date.slice(0, 4) !== "0000" ? date : null;
    }

    static fetch(seriesId, date, overrides = {}, refresh = "") {
        const id = typeof seriesId === "string" ? seriesId.trim().toUpperCase() : "";
        const day = TickerSheetsExactFred.date_(date);
        if (!/^[A-Z0-9_]{1,50}$/.test(id)) return TickerSheetsPublicData.failure("Use a supported FRED series ID.");
        if (!day) return TickerSheetsPublicData.failure("Use a date-valued cell or a valid YYYY-MM-DD date.");
        const source = "https://fred.stlouisfed.org/series/" + id;
        let deps, key;
        try {
            deps = TickerSheetsPublicData.dependencies(overrides);
            key = typeof deps.fredKey === "function" ? deps.fredKey() : deps.fredKey;
        } catch { return TickerSheetsPublicData.failure("FRED API key unavailable. Use the TickerSheets menu.", source); }
        if (typeof key !== "string" || !/^[a-z0-9]{32}$/.test(key)) return TickerSheetsPublicData.failure("FRED API key required. Use the TickerSheets menu.", source);
        return TickerSheetsPublicData.cached("fred-exact", id + ":" + day, 3600, services => {
            // These private request URLs never enter a result, error message or cache record.
            const parameters = "?series_id=" + encodeURIComponent(id) + "&api_key=" + encodeURIComponent(key) + "&file_type=json";
            const metadata = TickerSheetsPublicData.request("https://api.stlouisfed.org/fred/series" + parameters, services);
            if (metadata.http !== 200 || metadata.body.includes(key)) return TickerSheetsPublicData.failure("FRED series metadata unavailable.", source);
            const meta = JSON.parse(metadata.body);
            if (!meta || typeof meta !== "object" || Array.isArray(meta) || meta.error_code !== undefined || !Array.isArray(meta.seriess)
                || meta.seriess.length !== 1 || meta.seriess[0]?.id !== id) return TickerSheetsPublicData.failure("FRED series metadata unavailable.", source);
            if (typeof meta.seriess[0].units === "string" && meta.seriess[0].units.includes(key)) return TickerSheetsPublicData.failure("FRED series metadata unavailable.", source);
            const response = TickerSheetsPublicData.request("https://api.stlouisfed.org/fred/series/observations" + parameters
                + "&observation_start=" + day + "&observation_end=" + day + "&sort_order=desc&limit=1&units=lin&output_type=1", services);
            if (response.http !== 200 || response.body.includes(key)) return TickerSheetsPublicData.failure("FRED exact-date observation unavailable.", source);
            const payload = JSON.parse(response.body);
            if (!payload || typeof payload !== "object" || Array.isArray(payload) || payload.error_code !== undefined || !Array.isArray(payload.observations)
                || payload.units !== undefined && payload.units !== "lin" || payload.output_type !== undefined && payload.output_type !== 1
                || payload.observation_start !== undefined && payload.observation_start !== day || payload.observation_end !== undefined && payload.observation_end !== day
                || payload.offset !== undefined && payload.offset !== 0) {
                return TickerSheetsPublicData.failure("FRED returned an invalid exact-date response.", source);
            }
            if (payload.count !== undefined && payload.count !== payload.observations.length) {
                const echoed = payload.observations[0];
                // Some monthly requests echo a period-start row outside the exact window while count remains zero.
                // That row never supplies the requested day's value.
                if (payload.count === 0 && payload.observations.length === 1 && payload.units === "lin" && payload.output_type === 1
                    && payload.observation_start === day && payload.observation_end === day && payload.offset === 0
                    && echoed && typeof echoed === "object" && !Array.isArray(echoed) && echoed.date !== day
                    && TickerSheetsFred.date_(echoed.date) && echoed.date.slice(0, 4) !== "0000" && TickerSheetsFred.value_(echoed.value).valid) {
                    return TickerSheetsPublicData.failure("FRED has no observation on " + day + ".", source);
                }
                return TickerSheetsPublicData.failure("FRED returned an invalid exact-date response.", source);
            }
            if (!payload.observations.length) return TickerSheetsPublicData.failure("FRED has no observation on " + day + ".", source);
            if (payload.observations.length !== 1) return TickerSheetsPublicData.failure("FRED returned multiple observations for one date.", source);
            const row = payload.observations[0];
            if (!row || typeof row !== "object" || Array.isArray(row) || row.date !== day) return TickerSheetsPublicData.failure("FRED did not return the requested observation date.", source);
            const parsed = TickerSheetsFred.value_(row.value);
            if (!parsed.valid) return TickerSheetsPublicData.failure("FRED returned an invalid observation value.", source);
            if (parsed.value === null) return TickerSheetsPublicData.failure("FRED observation missing on " + day + ".", source);
            return { ok: true, status: "Available", seriesId: id, date: day, value: parsed.value, http: response.http, source,
                unit: typeof meta.seriess[0].units === "string" && meta.seriess[0].units ? meta.seriess[0].units : "Units unavailable" };
        }, deps, refresh);
    }
}

/**
 * FRED value for one exact observation date. Missing dates never use an earlier observation.
 * Values keep FRED's published units. Save your key through TickerSheets → API keys….
 * @param {string} seriesId FRED series ID, such as DGS10.
 * @param {Date|string} date A date-valued cell or YYYY-MM-DD text.
 * @param {number} refresh Optional editable refresh number.
 * @return {number|string} Numeric value or an explanatory N/A message.
 * @customfunction
 */
function TICKERSHEETS_FRED_VALUE(seriesId, date, refresh = "") {
    try {
        const data = TickerSheetsExactFred.fetch(seriesId, date, {}, refresh);
        return data.ok ? TickerSheetsPublicData.safe(data.value) : TickerSheetsPublicData.error(data);
    } catch { return "N/A: FRED exact-date value unavailable"; }
}

/** Expiration-only position arithmetic. All premiums are per share; cash outputs cover the whole position.
 * OIC definitions checked against the sources returned by references(). This model excludes fees,
 * taxes, dividends, financing, early exercise and changes in contract deliverables.
 */
class TickerSheetsStrategies {
    static names() { return ["Covered call", "Cash-secured put", "Call vertical", "Put vertical"]; }
    static references() { return [
        ["Covered call", "https://www.optionseducation.org/strategies/all-strategies/covered-call-buy-write"],
        ["Cash-secured put", "https://www.optionseducation.org/strategies/all-strategies/cash-secured-put"],
        ["Bull call vertical", "https://www.optionseducation.org/strategies/all-strategies/bull-call-spread-debit-call-spread"],
        ["Bear call vertical", "https://www.optionseducation.org/strategies/all-strategies/bear-call-spread-credit-call-spread"],
        ["Bull put vertical", "https://www.optionseducation.org/strategies/all-strategies/bull-put-spread-credit-put-spread"],
        ["Bear put vertical", "https://www.optionseducation.org/strategies/all-strategies/bear-put-spread"]
    ]; }
    static number_(value, zero = false) { return typeof value === "number" && Number.isFinite(value) && (zero ? value >= 0 : value > 0) ? value : null; }
    static date_(value, book) {
        if (value instanceof Date && Number.isFinite(value.getTime())) {
            if (typeof Utilities !== "undefined" && typeof Utilities.formatDate === "function") {
                try { return TickerSheetsStrategies.date_(Utilities.formatDate(value, book.getSpreadsheetTimeZone(), "yyyy-MM-dd"), book); }
                catch { return ""; }
            }
            return value.toISOString().slice(0, 10);
        }
        if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return "";
        const parsed = new Date(value + "T00:00:00.000Z");
        return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value ? value : "";
    }
    static input_(input) {
        if (!input || typeof input !== "object") return { error: "Strategy inputs are required." };
        const id = typeof input.strategy === "string" ? input.strategy.toLowerCase().replace(/[ _-]/g, "") : "";
        const name = { coveredcall: "Covered call", cashsecuredput: "Cash-secured put", callvertical: "Call vertical", putvertical: "Put vertical" }[id];
        if (!name) return { error: "Choose a supported strategy." };
        if (!Number.isSafeInteger(input.contracts) || input.contracts <= 0 || !Number.isSafeInteger(input.multiplier) || input.multiplier <= 0
            || !Number.isSafeInteger(input.contracts * input.multiplier)) return { error: "Contracts and multiplier must be positive whole numbers." };
        const expiration = typeof input.expiration === "string" ? TickerSheetsStrategies.date_(input.expiration) : "";
        if (!expiration) return { error: "Enter one valid YYYY-MM-DD expiration for all option legs." };
        const spot = TickerSheetsStrategies.number_(input.spot), ks = TickerSheetsStrategies.number_(input.shortStrike), ps = TickerSheetsStrategies.number_(input.shortPremium, true);
        if (ks === null || ps === null) return { error: "Enter a positive short strike and a nonnegative short premium." };
        if (name === "Covered call" && spot === null) return { error: "Enter the stock cost basis per share." };
        const vertical = name.endsWith("vertical"), kl = vertical ? TickerSheetsStrategies.number_(input.longStrike) : null, pl = vertical ? TickerSheetsStrategies.number_(input.longPremium, true) : 0;
        if (vertical && (kl === null || pl === null || kl === ks)) return { error: "Verticals require different positive strikes and nonnegative premiums." };
        return { strategy: name, spot, kl, pl, ks, ps, expiration, scale: input.contracts * input.multiplier };
    }
    static payoff_(data, price) {
        const credit = data.ps - data.pl;
        if (data.strategy === "Covered call") return (price - data.spot + credit - Math.max(price - data.ks, 0)) * data.scale;
        if (data.strategy === "Cash-secured put") return (credit - Math.max(data.ks - price, 0)) * data.scale;
        const long = data.strategy === "Call vertical" ? Math.max(price - data.kl, 0) : Math.max(data.kl - price, 0);
        const short = data.strategy === "Call vertical" ? Math.max(price - data.ks, 0) : Math.max(data.ks - price, 0);
        return (credit + long - short) * data.scale;
    }
    static calculate(input) {
        const data = TickerSheetsStrategies.input_(input);
        if (data.error) return { ok: false, error: data.error };
        const netPremium = (data.ps - data.pl) * data.scale, stockCost = data.strategy === "Covered call" ? data.spot * data.scale : 0;
        let candidate, structure = data.strategy, interval = false;
        if (data.strategy === "Covered call") candidate = data.spot - data.ps;
        else if (data.strategy === "Cash-secured put") candidate = data.ks - data.ps;
        else if (data.strategy === "Call vertical") {
            candidate = data.kl < data.ks ? data.kl - (data.ps - data.pl) : data.ks + (data.ps - data.pl);
            structure = data.kl < data.ks ? "Bull call vertical" : "Bear call vertical";
        } else {
            candidate = data.kl > data.ks ? data.kl + (data.ps - data.pl) : data.ks - (data.ps - data.pl);
            structure = data.kl > data.ks ? "Bear put vertical" : "Bull put vertical";
        }
        const low = data.kl === null ? 0 : Math.min(data.kl, data.ks), high = data.kl === null ? data.ks : Math.max(data.kl, data.ks);
        let breakeven = candidate >= low && candidate <= high ? candidate : null;
        const atZero = TickerSheetsStrategies.payoff_(data, 0), atTop = TickerSheetsStrategies.payoff_(data, high);
        if (!Number.isFinite(netPremium) || !Number.isFinite(stockCost) || !Number.isFinite(atZero) || !Number.isFinite(atTop)) return { ok: false, error: "The position amounts exceed the supported numeric range." };
        if (breakeven !== null) interval = (data.kl !== null && low > 0 && Math.abs(breakeven - low) < 1e-10 && Math.abs(TickerSheetsStrategies.payoff_(data, low)) < 1e-8)
            || (Math.abs(breakeven - high) < 1e-10 && Math.abs(atTop) < 1e-8);
        return { ok: true, strategy: data.strategy, expiration: data.expiration, initialCashflow: netPremium - stockCost, netPremium, stockCost,
            collateral: data.strategy === "Cash-secured put" ? data.ks * data.scale : 0,
            maxProfit: Math.max(atZero, atTop), maxLoss: Math.max(0, -Math.min(atZero, atTop)), breakeven,
            premiumType: netPremium > 0 ? "Net credit" : netPremium < 0 ? "Net debit" : "Zero net premium", structure,
            breakEvenNote: breakeven === null ? "No zero P/L stock price at or above zero for these inputs." : interval ? "Boundary shown; zero P/L can extend beyond this price." : "One stock price at expiration gives zero P/L.", error: "" };
    }
    static payoff(input, stockAtExpiry) {
        const data = TickerSheetsStrategies.input_(input), price = TickerSheetsStrategies.number_(stockAtExpiry, true);
        if (data.error || price === null) return null;
        const result = TickerSheetsStrategies.payoff_(data, price);
        return Number.isFinite(result) ? result : null;
    }
}

/** One ticker's public quote, fundamentals and calculated indicators as a labeled table. */
class TickerSheetsWatchRow {
    static keys() {
        return ["status", "price", "currency", "quote_time", "retrieved_at", "indicator_as_of", "return1d", "return1m", "return1y", "rsi14",
            "sma50", "sma200", "volatility20d", "trailing_pe", "eps_ttm", "market_cap", "target_price", "next_earnings", "source", "price_session",
            "atm_iv", "return3m", "return_ytd", "max_drawdown", "macd", "macd_signal", "average_volume20", "bar_count", "previous_rsi2", "previous_close"];
    }
    static unavailable_(status) {
        return { ...Object.fromEntries(TickerSheetsWatchRow.keys().map(key => [key, null])), status };
    }
    static data(ticker, overrides = {}, refresh = "") {
        let symbol;
        try { symbol = TickerSheetsData.normalizeTicker(ticker).yahooSymbol; }
        catch { return TickerSheetsPublicData.failure("Enter a supported ticker."); }
        return TickerSheetsPublicData.cached("watch-row:v1", symbol, 60, services => {
            const quote = TickerSheetsPublicData.quote(symbol, services, refresh), details = TickerSheetsPublicData.details(symbol, services, refresh);
            if (!quote.ok && !details.ok) return TickerSheetsPublicData.failure("Quote and fundamentals unavailable.");
            const chart = quote.chart || {}, history = quote.ok && Array.isArray(chart.history) ? chart.history : [];
            const technical = TickerSheetsData.calculate(history).summary, fields = details.fields || {};
            const selected = quote.ok ? quote.quote || TickerSheetsData.selectQuote(chart, details.details || {}) : {};
            const field = key => details.ok && Object.prototype.hasOwnProperty.call(fields, key) ? fields[key]?.value ?? null : null;
            const previous = technical.barCount > 1 ? history[technical.barCount - 2]?.close : null;
            const result = TickerSheetsWatchRow.unavailable_(quote.ok && details.ok ? "Available"
                : quote.ok ? "Quote available; fundamentals unavailable" : "Fundamentals available; quote unavailable");
            Object.assign(result, {
                price: selected.price ?? null, currency: chart.currency || null, quote_time: selected.quoteTime || quote.quoteTime || null,
                retrieved_at: quote.ok ? quote.retrievedAt || null : details.retrievedAt || null,
                indicator_as_of: technical.indicatorAsOf || null, return1d: technical.return1d, return1m: technical.return1m, return1y: technical.return1y,
                rsi14: technical.rsi14, sma50: technical.sma50, sma200: technical.sma200, volatility20d: technical.volatility20d,
                trailing_pe: field("trailing_pe"), eps_ttm: field("eps_ttm"), market_cap: field("market_cap"), target_price: field("target_price"),
                next_earnings: details.ok ? details.details?.nextEarnings?.dates?.[0] || field("earnings_date") : null,
                source: quote.ok ? quote.source || null : details.source || null, price_session: selected.session || null,
                return3m: technical.return3m, return_ytd: technical.returnYtd, max_drawdown: technical.maxDrawdown,
                macd: technical.macd, macd_signal: technical.macdSignal, average_volume20: technical.volumeAverage20,
                bar_count: history.filter(row => typeof row.close === "number" && Number.isFinite(row.close) && row.close > 0).length,
                previous_close: typeof previous === "number" && Number.isFinite(previous) && previous > 0 ? previous : null
            });
            // No option-chain or RSI2 request is made for other watchlist tickers.
            return { ok: true, fields: result, retrievedAt: result.retrieved_at || undefined };
        }, overrides, refresh);
    }
    static table(ticker, refresh = "", overrides = {}) {
        let data;
        try { data = TickerSheetsWatchRow.data(ticker, overrides, refresh); }
        catch { data = TickerSheetsPublicData.failure("Request or response unavailable."); }
        const fields = data.ok && data.fields ? data.fields : TickerSheetsWatchRow.unavailable_(TickerSheetsPublicData.error(data));
        return [["Field", "Value"], ...TickerSheetsWatchRow.keys().map(key => [key, TickerSheetsPublicData.safe(fields[key] === "" ? null : fields[key])])];
    }
}

/** Stock snapshot and technical indicators as a labeled table. @customfunction */
function TICKERSHEETS_WATCH_ROW(ticker, refresh = "") { return TickerSheetsWatchRow.table(ticker, refresh); }

/** Add API-key settings and a refresh command for formulas in any cell layout. */
function onOpen() {
    TickerSheetsMenu();
}

/** Rerun existing data formulas in the user's own layout. It never creates or populates tabs. */
function TickerSheetsRefreshData() {
    const book = SpreadsheetApp.getActiveSpreadsheet();
    if (!book) throw new Error("Open the spreadsheet before refreshing formulas.");
    const saved = [], pattern = /\b(?:TICKERSHEETS_QUOTE|TICKERSHEETS_PROVIDER_QUOTE|TICKERSHEETS_HISTORY|TICKERSHEETS_FUNDAMENTALS|TICKERSHEETS_OPTIONS|TICKERSHEETS_EXPIRATIONS|TICKERSHEETS_EARNINGS|TICKERSHEETS_FRED|TICKERSHEETS_FRED_VALUE|TICKERSHEETS_FIELD|TICKERSHEETS_RSI_TARGETS|TICKERSHEETS_WATCH_ROW|TICKERSHEETS_QUOTE_COMPARE|TICKERSHEETS_DATA_STATUS|TICKERSHEETS_STRATEGY|TICKERSHEETS_OPTION_MODEL)\s*\(/i;
    for (const sheet of book.getSheets()) {
        const formulas = sheet.getDataRange().getFormulas();
        for (let row = 0; row < formulas.length; row++) for (let col = 0; col < formulas[row].length; col++) {
            const formula = formulas[row][col];
            if (formula && !/^=FORMULATEXT\(/i.test(formula) && pattern.test(formula)) saved.push({ range: sheet.getRange(row + 1, col + 1), formula });
        }
    }
    if (saved.length) {
        TickerSheetsPublicData.setAutomaticRefresh(Date.now() % 2147483647);
        // Change the formula text briefly to make Sheets recalculate unchanged inputs.
        // Every cell keeps a valid formula even if execution is cancelled or times out.
        try { saved.forEach(item => item.range.setFormula("=(" + item.formula.slice(1) + ")")); SpreadsheetApp.flush(); }
        finally {
            let failed = false;
            for (const item of saved) { try { item.range.setFormula(item.formula); } catch { failed = true; } }
            if (failed) throw new Error("A formula could not be restored. Check cell permissions and try again.");
        }
    }
    book.toast(saved.length ? "Refreshing data. Wait for the results." : "No TickerSheets data formulas found.", "TickerSheets", 8);
    return { ok: true, recalculated: saved.length };
}
